186	    /**
187	     * @param addr byte array of a MAC address.
188	     * @return hex formatted MAC address.
189	     */
190	    public static String formatAddress(byte[] addr) {
191	        StringBuilder buf = new StringBuilder(24);
192	        for (byte b: addr) {
193	            StringUtil.byteToHexStringPadded(buf, b).append(':');
194	        }
195	        return buf.substring(0, buf.length() - 1);
196	    }
197	
198	    /**
199	     * @return positive - current is better, 0 - cannot tell from MAC addr, negative - candidate is better.
200	     */
201	    // visible for testing
202	    static int compareAddresses(byte[] current, byte[] candidate) {
203	        if (candidate == null || candidate.length < EUI48_MAC_ADDRESS_LENGTH) {
204	            return 1;
205	        }
206	
207	        // Must not be filled with only 0 and 1.
208	        boolean onlyZeroAndOne = true;
209	        for (byte b: candidate) {
210	            if (b != 0 && b != 1) {
211	                onlyZeroAndOne = false;
212	                break;
213	            }
214	        }
215	
216	        if (onlyZeroAndOne) {
217	            return 1;
218	        }
219	
220	        // Must not be a multicast address
221	        if ((candidate[0] & 1) != 0) {
222	            return 1;
223	        }
224	
225	        // Prefer globally unique address.
226	        boolean candidateIsUnique = (candidate[0] & 2) == 0;
227	        boolean currentIsUnique = current.length != 0 && (current[0] & 2) == 0;
228	        if (candidateIsUnique == currentIsUnique) {
229	            // Both or neither are globally unique: cannot tell them apart.
230	            return 0;
231	        }
232	        // Exactly one is globally unique; prefer it.
233	        return candidateIsUnique ? -1 : 1;
234	    }
235	
236	    /**
237	     * @return positive - current is better, 0 - cannot tell, negative - candidate is better
238	     */
239	    private static int compareAddresses(InetAddress current, InetAddress candidate) {
240	        return scoreAddress(current) - scoreAddress(candidate);
241	    }
242	
243	    private static int scoreAddress(InetAddress addr) {
244	        if (addr.isAnyLocalAddress() || addr.isLoopbackAddress()) {
245	            return 0;
246	        }
247	        if (addr.isMulticastAddress()) {
248	            return 1;
249	        }
250	        if (addr.isLinkLocalAddress()) {
251	            return 2;
252	        }
253	        if (addr.isSiteLocalAddress()) {
254	            return 3;
255	        }
256	
257	        return 4;
258	    }
